import{_ as t,o as a,c as i,ag as s}from"./chunks/framework.CxkNbRKf.js";const o="/nada-documentation/images/image55.png",n="/nada-documentation/images/image56.png",r="/nada-documentation/images/image57.png",l="/nada-documentation/images/image58.png",h="/nada-documentation/images/image59.png",d="/nada-documentation/images/image60.png",c="/nada-documentation/images/image61.png",g="/nada-documentation/images/image62.png",p="/nada-documentation/images/image63.png",m="/nada-documentation/images/image64.png",u="/nada-documentation/images/image65.png",f="/nada-documentation/images/image66.png",b="/nada-documentation/images/image67.png",w="/nada-documentation/images/image68.png",y="/nada-documentation/images/image69.png",_="/nada-documentation/images/image70.png",I=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/site-configurations.md","filePath":"admin-guide/web-ui/site-configurations.md","lastUpdated":1786379412000}'),S={name:"admin-guide/web-ui/site-configurations.md"};function T(v,e,q,A,k,D){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><h2 id="using-the-administrator-interface" tabindex="-1">Using the administrator interface <a class="header-anchor" href="#using-the-administrator-interface" aria-label="Permalink to &quot;Using the administrator interface&quot;">​</a></h2><p>All settings for the application are controlled via the Settings menu at the top of the Site Administration page.</p><p><img src="'+o+'" alt=""></p><p>There are seven main settings sections.</p><blockquote><p><img src="'+n+'" alt=""></p></blockquote><h2 id="general-site-settings" tabindex="-1">General site settings <a class="header-anchor" href="#general-site-settings" aria-label="Permalink to &quot;General site settings&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>The <strong>Website title</strong> will become the frontpage title of the NADA catalog. In the user interface:</p><p><img src="'+l+'" alt=""></p><p><strong>Website footer</strong>: The footer text can be changed in this field. This displays at the bottom of your site page when your theme outputs it (see <a href="/nada-documentation/installation-guide/configurations/customizing-themes.html">Customizing themes</a>).</p><p><img src="'+h+'" alt=""></p><p><strong>Default home page</strong>: The initial page that loads when a user visits the NADA site can be set here. In this case the catalog page is set to open by default. For a full guide (menus, static views, and the default <code>home.php</code> template), see <a href="/nada-documentation/admin-guide/web-ui/customizing-home-page.html">Customizing the home page</a>.</p><p><strong>Webmaster name</strong>: The name of the webmaster can be set here. This is the name that will be used in system emails sent to users.</p><p><strong>Webmaster email</strong>: Enter the webmaster email address here. This should be the address that will be used in communication with users. Typically, this is a general enquiries email set up by the organization and not a personal email address for a particular person. Note: to avoid mail systems rejecting mail as spam make sure to enter an address here that is on the same domain as the server used in the email settings at setup.</p><p><strong>Cache expiration time</strong>: A cache folder stores pre- generated pages of the site to allow for faster browsing by the user. Set the time that the Cache takes to expire. By default, it is set to 2 hours (in milliseconds).</p><p><strong>Disable caching</strong>: If it is desired to turn off caching then select &quot;no&quot; here. Sometimes it is useful to turn off caching when developing or updating a site to ensure that content changes become immediately visible on the front-end without having to wait for the cache to expire and the new changes to show. Turn this back on to speed up page loading for users.</p><p>Click <strong>Update</strong> to save all settings.</p><h2 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h2><p>To change the language of the application, expand the language section and choose the desired language. Click <strong>Update</strong> to save and apply the setting.</p><p><img src="'+d+'" alt=""></p><p>The change of language will apply to both the user and the administrator interfaces.</p><p><img src="'+c+'" alt=""></p><p><img src="'+g+'" alt=""></p><p>If you see content that is not in the selected language, it means that some translations are missing. If a translation is missing, or if you think that the translation is not accurate, you can add/edit the translation yourself. See the section &quot;Translating NADA&quot;.</p><p><img src="'+p+'" alt=""></p><p><img src="'+m+'" alt=""></p><p><img src="'+u+'" alt=""></p><h2 id="use-of-html-editor" tabindex="-1">Use of HTML Editor <a class="header-anchor" href="#use-of-html-editor" aria-label="Permalink to &quot;Use of HTML Editor&quot;">​</a></h2><p>A basic HTML editor is provided in the menu and page creating section of the application. This setting allows this to be turned on or off.</p><p><img src="'+f+'" alt=""></p><h2 id="survey-catalog-settings" tabindex="-1">Survey catalog settings <a class="header-anchor" href="#survey-catalog-settings" aria-label="Permalink to &quot;Survey catalog settings&quot;">​</a></h2><p><img src="'+b+'" alt=""></p><p><strong>Catalog folder</strong>: This is the folder where the files for the study are stored on the server. This includes the DDI, eternal resources and data files. This folder can be moved to a location outside the web root as described in the installation instructions in Chapter 1. Enter either relative or absolute paths to the folder location.</p><p><strong>DDI import folder</strong>: This is the folder where DDI&#39;s can be placed in order to use the bulk study import function in the NADA. In NADA3 files had to be physically copied to this folder on the server, but this is no longer necessary in NADA 4. Files can now be directly uploaded to this folder from the Site Administration -- Manage Studies page page.</p><ul><li><p>Select the vocabulary to use for the topic filter. By default, this is set to the CESSDA classification as recommended in the IHSN templates supplied at IHSN.org for the Nesstar Metadata Publisher.</p></li><li><p>Enable or disable the Country filter on the user interface search page here. If the catalog only contains studies for one country, then turning this filter off is recommended.</p></li><li><p>Enable or disable the Topic filter on the user interface search page here. If no topics have been defined in the DDI&#39;s being uploaded, then it is recommended to turn this filter off (disable).</p></li><li><p>Enable or disable the Year filter on the user interface search page here.</p></li><li><p>Enable or disable the Collection filter on the user interface search page here. If no collections have been defined, then it is recommended to disable this filter.</p></li><li><p>Enable or disable the Data access filter on the user interface search page here. This filter is not needed if there are very few studies in the catalog or if all studies are set to the same access type.</p></li><li><p>This section controls the order in which the filters appear on the search page. Enter numbers here that rank the order of the filters in the order they should be displayed.</p></li></ul><p><strong>Catalog search page size</strong>: This setting determines how many studies are displayed by default to the user on the search page -- catalog view.</p><p><img src="'+w+'" alt=""></p><h2 id="site-login" tabindex="-1">Site login <a class="header-anchor" href="#site-login" aria-label="Permalink to &quot;Site login&quot;">​</a></h2><p><strong>Password protected website:</strong> By default, a NADA catalog created on a web server will be accessible to all users with access to the URL (intranet or internet). Users will only need to register and login when they want to request access, or access, non-public data. In some cases, however, a catalog administrator may want to restrict the access to the catalog to authorized persons only. This can be done by requiring that all users login to access the website, by selecting the option &quot;Requires all users to login to access the website&quot;. <em>[how do they get a password?]</em></p><p><strong>Login timeout</strong>: determines how long a user will stay logged in. After the time indicated here (a positive value in minutes), the user will be automatically logged out.</p><p><strong>Minimum password length</strong>: Sets the minimum length for passwords created by the users at registration, or for manual user creation by administrators. The use of strong passwords is recommended.</p><p><img src="'+y+'" alt=""></p><h2 id="search-provider" tabindex="-1">Search provider <a class="header-anchor" href="#search-provider" aria-label="Permalink to &quot;Search provider&quot;">​</a></h2><p>Under Site configurations you can choose how the public catalog search runs:</p><table tabindex="0"><thead><tr><th>Provider</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Database (db)</strong></td><td>Built-in MySQL/MariaDB/SQL Server search (default; no Solr required)</td></tr><tr><td><strong>Solr</strong></td><td>Full-text search via Apache Solr</td></tr><tr><td><strong>OpenSearch</strong> / <strong>Semantic</strong></td><td>Other search backends (separate configuration)</td></tr></tbody></table><p>To use Solr: install and index Solr first, then set <strong>Search provider</strong> to <strong>Solr</strong>. Full steps: <a href="/nada-documentation/admin-guide/web-ui/solr.html">Solr search</a> (admin) · <a href="/nada-documentation/installation-guide/installation-solr.html">Solr install</a>.</p><h2 id="smtp-settings" tabindex="-1">SMTP settings <a class="header-anchor" href="#smtp-settings" aria-label="Permalink to &quot;SMTP settings&quot;">​</a></h2><p>NADA may need to be able to send emails to users. This will be the case when access to some datasets (public use files, or licensed access datasets) require that users be registered. Email communications will be used by NADA to (i) confirm and activate the user registration, and (ii) to inform users of the status of their requests for access to licensed datasets. To allow this, an email account dedicated to NADA must be created (possibly on a commercial email application like G-mail), and the SMTP must be configured to enable this account.</p><p>The SMTP settings are set by editing the config/email.php file (which cannot be done using the administrator interface). Once done, it is essential to test the email settings. This can be done using the &quot;Test email configurations&quot; button.</p><p><img src="'+_+'" alt=""></p><p>Another way to test if the email settings are working is to use the &quot;forgot password&quot; option from the user login page. If no mail is received when doing this test, the mail settings must be corrected. If necessary, check with the ISP or server administrator for the correct settings.</p><h2 id="using-the-api" tabindex="-1">Using the API <a class="header-anchor" href="#using-the-api" aria-label="Permalink to &quot;Using the API&quot;">​</a></h2><p>The site settings cannot be changed using the API.</p>',54)])])}const x=t(S,[["render",T]]);export{I as __pageData,x as default};
